
const $=id=>document.getElementById(id);
const R=["gold","stone","wood","food"],NM={gold:"Gold",stone:"Stone",wood:"Wood",food:"Food"},CL={gold:"g",stone:"s",wood:"w",food:"f"},IC={gold:"🪙",stone:"🪨",wood:"🪵",food:"🍖"};
const BT={hall:{n:"Town Hall",e:"🏰",c:{},t:0},
house:{n:"House",e:"🏠",c:{wood:30,stone:10},t:8,pop:4,p:"gold",r:.5},
farm:{n:"Farm",e:"🌾",c:{wood:25,gold:20},t:6,p:"food",r:.8,w:1},
lumber:{n:"Lumber camp",e:"🌲",c:{gold:30,stone:5},t:6,p:"wood",r:.8,w:1},
quarry:{n:"Quarry",e:"⛏️",c:{gold:40,wood:30},t:8,p:"stone",r:.6,w:1},
barracks:{n:"Barracks",e:"⚔️",c:{wood:60,stone:40,gold:30},t:15,tr:12},
tower:{n:"Watchtower",e:"🗼",c:{stone:60,wood:40,gold:40},t:12,d:40},
wall:{n:"Wall",e:"🧱",c:{stone:25},t:4,d:10}};
const TROOPS={sword:{n:"Swordsman",p:5,l:4,c:{food:15,gold:10}},archer:{n:"Spearman",p:8,l:6,c:{wood:15,gold:20}},knight:{n:"Knight",p:20,l:10,c:{gold:50,stone:20}}};
const HEROES=[{id:"aria",n:"Aria the Bold",p:60,c:{gold:300,stone:100}},{id:"brok",n:"Brok Ironfist",p:100,c:{gold:500,stone:200}},{id:"sable",n:"Sable the Shadow",p:140,c:{gold:700,stone:300}},{id:"isolde",n:"Isolde Frostbane",p:190,c:{gold:950,stone:450,wood:200}}];
const DRAGON={n:"Cinder, the Ember Dragon",p:250,c:{gold:800,stone:400,food:200}};
const ISLANDS=[{n:"Mossy Isle",need:40,t:15,r:{gold:120,wood:80}},{n:"Skull Shoals",need:120,t:25,r:{gold:300,stone:200}},{n:"Frostfang Atoll",need:300,t:40,r:{gold:700,stone:400,food:300}},{n:"Dragon’s Rest",need:600,t:60,r:{gold:1500,stone:900,wood:600}}];
const ETYPE=["sword","archer","knight"],COUNTER={sword:"knight",archer:"sword",knight:"archer"},EN={sword:"brutes",archer:"skirmishers",knight:"stalkers"};
const CAP=40,BLD=2;let S,tab="build",sel=-1,arm=0,mv=-1;
function fresh(){const g=Array(80).fill(null);g[34]={t:"hall",lv:1,b:0};g[33]={t:"house",lv:1,b:0,s:0};g[35]={t:"lumber",lv:1,b:0,s:0};
 return{res:{gold:150,stone:60,wood:120,food:150},g,troops:{sword:0,archer:0,knight:0},q:[],heroes:[],dragon:false,wave:0,raidIn:300,protection:300,battle:null,quest:null,done:[],log:[],speed:1,wins:0,last:null,inv:{}}}
S=fresh();
const cnt=t=>S.g.filter(x=>x&&x.t===t).length,nb=t=>S.g.filter(x=>x&&x.t===t&&!x.b).length;
const busy=()=>S.g.filter(x=>x&&x.b>0).length;
const sc=(c,m)=>{const o={};for(const k in c)o[k]=Math.ceil(c[k]*m);return o};
const bcost=t=>sc(BT[t].c,Math.pow(1.25,cnt(t))),upCost=x=>sc(BT[x.t].c,Math.pow(1.8,x.lv));
const pop=()=>2+S.g.reduce((a,x)=>a+(x&&!x.b&&BT[x.t].pop?BT[x.t].pop+2*(x.lv-1):0),0);
const nw=()=>2*S.g.filter(x=>x&&!x.b&&BT[x.t].w).length;
const effv=()=>Math.min(1,pop()/Math.max(1,nw()));
const tCap=()=>6+S.g.reduce((a,x)=>a+(x&&!x.b&&BT[x.t].tr?BT[x.t].tr*x.lv:0),0);
const def=()=>S.g.reduce((a,x)=>a+(x&&!x.b&&BT[x.t].d?BT[x.t].d*x.lv:0),0);
const tCount=()=>S.troops.sword+S.troops.archer+S.troops.knight;
const mm=(k,e)=>!e?1:COUNTER[k]===e?1.5:COUNTER[e]===k?.7:1;
function power(e){let p=0;for(const k in TROOPS)p+=S.troops[k]*TROOPS[k].p*mm(k,e);S.heroes.forEach(id=>p+=HEROES.find(h=>h.id===id).p);if(S.dragon)p+=DRAGON.p;return Math.round(p*(S.quest?.5:1))+def()}
const army=()=>power()-def();
const enemyType=w=>ETYPE[w%3],enemyStr=w=>Math.round(15+w*28+(w%2===1?0:w*10)),counterOf=e=>Object.keys(COUNTER).find(k=>COUNTER[k]===e);
const can=c=>Object.keys(c).every(k=>S.res[k]>=c[k]),pay=c=>{for(const k in c)S.res[k]-=c[k]};
const fmt=c=>Object.keys(c).map(k=>`<span class="${CL[k]}">${c[k]} ${NM[k]}</span>`).join(" ");
function log(t,cls=""){S.log.unshift(`<p class="${cls}">${t}</p>`);S.log=S.log.slice(0,40)}
function btn(a,v,label,ok,cls=""){return`<button class="${cls}" data-a="${a}" ${v!==undefined?`data-v="${v}"`:""} ${ok?"":"disabled"}>${label}</button>`}
function fin(x){x.b=0;if(x.up){x.lv++;x.up=0}log(`${BT[x.t].n} is ready.`)}
function casualties(f){let n=0;for(const k in S.troops){const d=Math.floor(S.troops[k]*f);S.troops[k]-=d;n+=d}return n}
function report(win,who,et,str,p,extra){if(win)S.wins++;const t=`${who} (${EN[et]}, strength ${str}) met your power of ${p}. ${win?"Victory!":"Defeat."} ${extra}`;S.last={win,t};log(t,win?"win":"lose")}
function raid(){
 if(S.battle)return; const w=S.wave+1, e=enemyType(w), p=power(e), q=enemyStr(w); S.battle={round:0,p,q,hp:Math.max(1,p)*10,ehp:q*10,hit:0,ehit:0,units:Object.fromEntries(Object.keys(TROOPS).map(k=>[k,S.troops[k]])),heroes:[...S.heroes],win:p>=q};
}
function resolveRaid(){
 S.wave++;const et=enemyType(S.wave),str=S.battle.q,who=`A horde of ${[...new Set(enemyGroup(S.wave).map(m=>m.n))].join(" and ")}`,p=S.battle.p;
 if(p>=str){const loot={gold:40+S.wave*20,stone:15+S.wave*8};for(const k in loot)S.res[k]+=loot[k];const dr=rollDrops(enemyGroup(S.wave).length,S.wave);report(true,who,et,str,p,`Loot: ${loot.gold} gold, ${loot.stone} stone. Drops: ${dropHTML(dr)}. Troops lost: ${casualties(.08)}.`)}
 else{for(const k of["gold","food","wood"])S.res[k]=Math.floor(S.res[k]*.65);casualties(.3);S.g.forEach(x=>{if(x&&x.s)x.s*=.4});report(false,who,et,str,p,"Raiders took 35% of stockpiles, emptied your stores and killed 30% of troops.")}
 S.raidIn=70+Math.floor(Math.random()*30);S.battle=null;showResult()}
const ACT={
 tab(v){tab=v},
 tile(i){i=+i;if(mv>=0&&S.g[mv]&&!S.g[i]){const b=S.g[mv];S.g[i]=b;S.g[mv]=null;log(`Moved ${BT[b.t].n}.`);mv=-1;sel=i;tab="build";return}mv=-1;sel=i;tab="build";const x=S.g[i];if(x&&x.s>=1){const n=Math.floor(x.s);S.res[BT[x.t].p]+=n;x.s-=n}},
 sell(k){if(S.inv[k]>0){S.inv[k]--;S.res.gold+=ITEMS[k].v}},
 sellk(k){S.res.gold+=(S.inv[k]||0)*ITEMS[k].v;S.inv[k]=0},
 sellall(){S.res.gold+=invValue();S.inv={}},
 move(){if(S.g[sel])mv=sel},
 cancelmove(){mv=-1},
 place(t){const c=bcost(t);if(sel>=0&&!S.g[sel]&&can(c)&&busy()<BLD){pay(c);const d=BT[t];S.g[sel]={t,lv:1,b:d.t,bt:d.t,s:0};log(`Started building: ${d.n}.`)}},
 up(){const x=S.g[sel];if(!x||x.b||x.t==="hall")return;const c=upCost(x);if(can(c)&&busy()<BLD){pay(c);x.b=x.bt=BT[x.t].t*(x.lv+1);x.up=1}},
 demo(){const x=S.g[sel];if(x&&x.t!=="hall"){S.g[sel]=null;mv=-1;log("Building demolished.")}},
 train(k){const T=TROOPS[k];if(nb("barracks")&&can(T.c)&&tCount()+S.q.length<tCap()){pay(T.c);S.q.push({k,l:T.l})}},
 hero(id){const h=HEROES.find(x=>x.id===id);if(can(h.c)&&!S.heroes.includes(id)){pay(h.c);S.heroes.push(id);log(`${h.n} has joined your banner.`,"win")}},
 dragon(){if(S.heroes.length&&can(DRAGON.c)&&!S.dragon){pay(DRAGON.c);S.dragon=true;log("Cinder the dragon awakens and bows to you.","win")}},
 quest(i){i=+i;const q=ISLANDS[i];if(!S.quest&&army()>=q.need){S.quest={i,left:q.t};log(`Army sets sail for ${q.n}. Army defense is halved while away.`)}},
 speed(){S.speed=S.speed===1?2:S.speed===2?5:1},
 reset(){if(arm){arm=0;try{localStorage.removeItem("emberhold2")}catch(e){}S=fresh();sel=-1;mv=-1;log("A new realm begins.")}else{arm=1;setTimeout(()=>{arm=0;draw()},3000)}}
};
document.addEventListener("pointerdown",e=>{const b=e.target.closest("[data-a]");if(!b||b.disabled)return;e.preventDefault();ACT[b.dataset.a](b.dataset.v);draw()});
function step(){
 const ef=effv();
 S.g.forEach(x=>{if(!x)return;if(x.b>0){if(--x.b<=0)fin(x);return}const d=BT[x.t];if(d.p)x.s=Math.min(CAP,(x.s||0)+d.r*(1+.4*(x.lv-1))*(d.w?ef:1))});
 S.q.slice(0,nb("barracks")).forEach(q=>q.l--);
 S.q=S.q.filter(q=>q.l>0||(S.troops[q.k]++,false));
 if(!S.battle){if(S.protection>0)S.protection--;if(--S.raidIn<=0)raid();}
 if(S.quest&&--S.quest.left<=0){const q=ISLANDS[S.quest.i];for(const k in q.r)S.res[k]+=q.r[k];const lost=casualties(.1),dr=rollDrops(2,S.wave+8+S.quest.i*6);if(!S.done.includes(S.quest.i))S.done.push(S.quest.i);log(`Quest cleared: ${q.n}! Reward: ${Object.keys(q.r).map(k=>q.r[k]+" "+k).join(", ")}. ${lost} troops fell. Drops: ${dropHTML(dr)}.`,"win");S.quest=null}
}
function tick(){if(S.battle)battleStep();else for(let i=0;i<(S.protection>0?1:(S.speed||1))&&!S.battle;i++)step();draw();save()}
function tileHTML(x,i){
 const c="tile"+(sel===i?" sel":"");
 if(!x)return`<button class="${c}" data-a="tile" data-v="${i}" aria-label="Empty plot"></button>`;
 const st=Math.floor(x.s||0);
 return`<button class="${c}" data-a="tile" data-v="${i}" aria-label="${BT[x.t].n}">${BT[x.t].e}${x.lv>1?`<i class="lv">${x.lv}</i>`:""}${x.b?`<u class="pb" style="text-decoration:none"><b style="width:${100-x.b/x.bt*100}%"></b></u>`:""}${st>=5?`<i class="bub">${st}</i>`:""}</button>`}
const GOALS=[["Build a house for gold and villagers",()=>cnt("house")>=2],["Build a farm and a quarry",()=>cnt("farm")&&cnt("quarry")],["Build a barracks",()=>cnt("barracks")],["Train 5 troops",()=>tCount()>=5],["Build a watchtower",()=>cnt("tower")],["Beat your first raid",()=>S.wins>=1],["Recruit a hero",()=>S.heroes.length],["Clear Mossy Isle",()=>S.done.includes(0)],["Awaken the dragon",()=>S.dragon],["Clear Dragon’s Rest",()=>S.done.includes(3)]];
const PANEL={
build(){let h=mv>=0&&S.g[mv]?`<div class="alert" style="border-color:var(--gold);margin-bottom:8px">Moving ${BT[S.g[mv].t].n}: tap an empty plot. <button class="sm alt" data-a="cancelmove">Cancel</button></div>`:"";const x=S.g[sel];
 if(x){const d=BT[x.t];h+=`<h2>${d.e} ${d.n} Lv ${x.lv}</h2>`;
  if(x.b)h+=`<p class="m">Working on it: ${x.b}s left.</p>`;
  else{if(d.p)h+=`<p class="m">Makes ${(d.r*(1+.4*(x.lv-1))).toFixed(2)} ${NM[d.p]}/s${d.w?" (needs 2 villagers)":""}. Tap to collect.</p>`;if(d.d)h+=`<p class="m">Defense +${d.d*x.lv}</p>`;if(d.tr)h+=`<p class="m">Troop room +${d.tr*x.lv}. Trains troops.</p>`;if(d.pop)h+=`<p class="m">Houses ${d.pop+2*(x.lv-1)} villagers.</p>`;
   h+=`<div class="row"><div>Move<small>Free. Tap Move, then an empty plot.</small></div>${mv===sel?btn("cancelmove",undefined,"Cancel",1,"alt"):btn("move",undefined,"Move",1)}</div>`;if(x.t!=="hall"){const c=upCost(x);h+=`<div class="row"><div>Upgrade to Lv ${x.lv+1}<small>${fmt(c)}</small></div>${btn("up",undefined,"Upgrade",can(c)&&busy()<BLD)}</div><div class="row"><div>Remove this building</div>${btn("demo",undefined,"Demolish",1,"alt")}</div>`}}}
 else if(sel>=0)h+=`<h2>Empty plot</h2>`+Object.keys(BT).filter(k=>k!=="hall").map(k=>{const d=BT[k],c=bcost(k);return`<div class="row"><div>${d.e} ${d.n}<small>${d.t}s. ${fmt(c)}</small></div>${btn("place",k,"Build",can(c)&&busy()<BLD)}</div>`}).join("");
 else h+=`<h2>Your village</h2><p class="m">Tap an empty plot to build. Two builders work at once. Farms, lumber camps and quarries each need 2 villagers, and houses provide them.</p>`;
 return h},
army(){const ne=enemyType(S.wave+1),ns=enemyStr(S.wave+1),ep=power(ne);
 let h=`<h2>Barracks: troops ${tCount()}+${S.q.length} queued / ${tCap()}</h2>${nb("barracks")?"":"<p class='m'>Build a barracks to train troops.</p>"}`+Object.keys(TROOPS).map(k=>{const t=TROOPS[k];return`<div class="row"><div class="who">${pic(SOL[k])}<div>${t.n} x${S.troops[k]}<small>Power ${t.p}, ${t.l}s. ${fmt(t.c)}</small></div></div>${btn("train",k,"Train",nb("barracks")&&can(t.c)&&tCount()+S.q.length<tCap())}</div>`}).join("");
 h+=`<div class="alert" style="margin-top:8px"><div class="grp">${enemyGroup(S.wave+1).map(m=>pic(m)).join("")}</div>Next: ${"Monster horde"}, ${EN[ne]}, strength about <b>${ns}</b>. Counter with <b>${TROOPS[counterOf(ne)].n}</b> troops (x1.5). Your power: <b>${ep}</b> ${ep>=ns?"(enough)":"(too low)"} including <b>${def()}</b> from towers and walls.</div>`;
 if(S.last)h+=`<div class="alert" style="border-color:${S.last.win?"var(--food)":"var(--red)"};margin-top:8px"><b>Last battle:</b> ${S.last.t}</div>`;
 return h+`<p><button class="sm" data-a="speed">Speed x${S.speed||1}</button> <button class="sm alt" data-a="reset">${arm?"Tap again to confirm":"New realm"}</button></p>`},
heroes(){return`<h2>Heroes and dragon</h2>`+HEROES.map(x=>`<div class="row"><div class="who">${pic(HIMG[x.id])}<div>${x.n}<small>Power +${x.p}. ${fmt(x.c)}</small></div></div>${S.heroes.includes(x.id)?"<b class='f'>Recruited</b>":btn("hero",x.id,"Recruit",can(x.c))}</div>`).join("")+`<div class="row"><div>${DRAGON.n}<small>Power +${DRAGON.p}. Needs a hero. ${fmt(DRAGON.c)}</small></div>${S.dragon?"<b class='f'>Awake</b>":btn("dragon",undefined,"Awaken",S.heroes.length>0&&can(DRAGON.c))}</div>`},
world(){return`<h2>World map: island quests</h2>`+ISLANDS.map((q,i)=>{const a=S.quest&&S.quest.i===i;return`<div class="row"><div>🏝️ ${q.n}${S.done.includes(i)?" ✔":""}<small>Army power ${q.need}+, ${q.t}s. ${fmt(q.r)}</small>${a?`<div class="bar"><i style="width:${100-S.quest.left/q.t*100}%;background:var(--food)"></i></div>`:""}</div>${btn("quest",i,a?"Sailing":"Sail",!S.quest&&army()>=q.need)}</div>`}).join("")},
loot(){const ids=Object.keys(S.inv).filter(k=>S.inv[k]>0).sort((a,b)=>ITEMS[b].r-ITEMS[a].r);
 let h=`<h2>Loot</h2><p class="m">${RAR.map((r,i)=>`<b class="r${i}">${r}</b>`).join(" · ")}. Monsters drop items. Sell them for gold.</p>`;
 if(!ids.length)return h+`<p class="m">Nothing yet. Win a raid to collect drops.</p>`;
 h+=`<div class="row"><div>Everything<small>${invCount()} items</small></div>${btn("sellall",undefined,`Sell all (${invValue()} gold)`,1)}</div>`;
 return h+ids.map(k=>{const it=ITEMS[k],n=S.inv[k];return`<div class="row"><div><b class="r${it.r}">${it.e} ${it.n}</b> x${n}<small class="r${it.r}">${RAR[it.r]}, ${it.v} gold each</small></div><div style="display:flex;gap:4px">${btn("sell",k,"Sell 1",1,"sm")}${btn("sellk",k,"Sell all",1,"sm alt")}</div></div>`}).join("")},
log(){return`<h2>Chronicle</h2><div id="log">${S.log.join("")||"<p>Your village is quiet. Build something.</p>"}</div>`}};
function draw(){
 $("res").innerHTML=R.map(k=>`<span class="${CL[k]}">${IC[k]} <b>${Math.floor(S.res[k])}</b></span>`).join("")+`<span>👷 <b>${busy()}/${BLD}</b></span><span>👥 <b>${nw()}/${pop()}</b></span><span>⚔️ <b>${power()}</b></span><span>⭐ Lv <b>${lvl()[0]}</b> <span style="display:inline-block;width:56px;height:6px;background:var(--bg);border-radius:3px;vertical-align:middle;overflow:hidden"><i style="display:block;height:100%;width:${lvl()[1]}%;background:var(--gold)"></i></span></span>`;
 const g=GOALS.find(x=>!x[1]());$("goal").innerHTML=`<div class="alert" style="border-color:var(--gold)"><b>Next goal:</b> ${g?g[0]:"Your realm is legendary. Keep defending it."}</div>`;
 const ne=enemyType(S.wave+1);$("raid").innerHTML=`Raid in <b>${S.raidIn}s</b>: ${"Monster horde"} (${EN[ne]})<div class="bar"><i style="width:${Math.max(0,100-S.raidIn)}%"></i></div>`;
 if(S.protection>0)$("raid").innerHTML=`<b>Beginner protection · ${S.protection}s remaining</b> — build and train before the first raid.`;if(S.battle)$("raid").innerHTML=battleHUD();$("grid").innerHTML=iso();
 $("tabs").innerHTML=[["build","Village"],["army","Army"],["heroes","Heroes"],["world","World"],["loot","Loot"+(invCount()?` (${invCount()})`:"")],["log","Log"]].map(([k,n])=>`<button class="${tab===k?"":"alt"}" data-a="tab" data-v="${k}">${n}</button>`).join("");
 $("panel").innerHTML=PANEL[tab]()}
const SPR={"hall":[{"u":"data:image/webp;base64,","w":124,"h":125}],"house":[{"u":"data:image/webp;base64,","w":56,"h":64},{"u":"data:image/webp;base64,","w":58,"h":72},{"u":"data:image/webp;base64,","w":62,"h":62}],"tower":[{"u":"data:image/webp;base64,","w":38,"h":66},{"u":"data:image/webp;base64,","w":42,"h":64},{"u":"data:image/webp;base64,","w":44,"h":74}],"barracks":[{"u":"data:image/webp;base64,","w":86,"h":86},{"u":"data:image/webp;base64,","w":88,"h":86},{"u":"data:image/webp;base64,","w":90,"h":92}],"lumber":[{"u":"data:image/webp;base64,","w":58,"h":55}],"quarry":[{"u":"data:image/webp;base64,","w":64,"h":52}],"farm":[{"u":"data:image/webp;base64,","w":40,"h":59}]};
function spr(x){const a=SPR[x.t];return a?a[Math.min(x.lv,a.length)-1]:null}
function img(s,cx,cy){return`<image href="${s.u}" x="${cx-s.w/2}" y="${cy+17-s.h}" width="${s.w}" height="${s.h}"/>`}
const SOL={"sword":{"u":"data:image/webp;base64,","w":41,"h":44},"archer":{"u":"data:image/webp;base64,","w":53,"h":48},"knight":{"u":"data:image/webp;base64,","w":48,"h":44}},HIMG={"aria":{"u":"data:image/webp;base64,","w":52,"h":48},"brok":{"u":"data:image/webp;base64,","w":48,"h":48},"sable":{"u":"data:image/webp;base64,","w":41,"h":46},"isolde":{"u":"data:image/webp;base64,","w":37,"h":48}},MON={"sword":[{"u":"data:image/webp;base64,","w":58,"h":46,"n":"Spiked Brute"},{"u":"data:image/webp;base64,","w":52,"h":46,"n":"Shield Golem"},{"u":"data:image/webp;base64,","w":60,"h":46,"n":"Thorn Crab"}],"archer":[{"u":"data:image/webp;base64,","w":48,"h":46,"n":"Spear Imp"},{"u":"data:image/webp;base64,","w":42,"h":46,"n":"Gloom Wraith"},{"u":"data:image/webp;base64,","w":59,"h":46,"n":"Wing Fiend"}],"knight":[{"u":"data:image/webp;base64,","w":63,"h":46,"n":"Blade Spider"},{"u":"data:image/webp;base64,","w":47,"h":46,"n":"Gravel Wyrm"},{"u":"data:image/webp;base64,","w":58,"h":46,"n":"Scorpion Stalker"}]};
const RAR=["Common","Uncommon","Rare","Epic","Legendary"];
const ITEMS={scrap:{n:"Scrap Iron",e:"🔩",r:0,v:10},claw:{n:"Rusty Claw",e:"🦴",r:0,v:14},plate:{n:"Spiked Plate",e:"🛡️",r:1,v:38},chain:{n:"Chain Coil",e:"⛓️",r:1,v:45},crystal:{n:"Void Crystal",e:"🔮",r:2,v:130},eye:{n:"Glowing Eye",e:"👁️",r:2,v:160},fang:{n:"Wyrm Fang",e:"🦷",r:3,v:450},core:{n:"Wraith Core",e:"💠",r:3,v:520},heart:{n:"Titan Heart",e:"❤️",r:4,v:1800},scale:{n:"Dragon Scale",e:"🐲",r:4,v:2400}};
const invValue=()=>Object.keys(S.inv).reduce((a,k)=>a+S.inv[k]*ITEMS[k].v,0),invCount=()=>Object.values(S.inv).reduce((a,b)=>a+b,0);
function rollDrops(n,w){const out=[];for(let i=0;i<n;i++){const wt=[55,27*(1+.05*w),12*(1+.08*w),5*(1+.1*w),1+.12*w];let r=Math.random()*wt.reduce((a,b)=>a+b),t=0;while(t<4&&r>=wt[t]){r-=wt[t];t++}const pool=Object.keys(ITEMS).filter(k=>ITEMS[k].r===t),k=pool[Math.floor(Math.random()*pool.length)];S.inv[k]=(S.inv[k]||0)+1;out.push(k)}return out}
function dropHTML(d){const c={};d.forEach(k=>c[k]=(c[k]||0)+1);return Object.keys(c).map(k=>`<b class="r${ITEMS[k].r}">${ITEMS[k].e} ${ITEMS[k].n}${c[k]>1?" x"+c[k]:""}</b>`).join(", ")}
function enemyGroup(w){const n=Math.min(5,2+Math.floor(w/2)),l=MON[enemyType(w)];return Array.from({length:n},(_,j)=>l[(w+j)%3])}
function pic(s){return`<img src="${s.u}" alt="">`}
function sdraw(s,x,y){return`<ellipse cx="${x}" cy="${y}" rx="${Math.max(8,s.w/2.2)}" ry="3.5" fill="#000" opacity=".28"/><image href="${s.u}" x="${x-s.w/2}" y="${y+1-s.h}" width="${s.w}" height="${s.h}"/>`}
const OFF=[[-30,12],[34,10],[-12,24],[16,26],[-40,28],[44,26]];
function squad(cx,cy){const c={...S.troops},q=[];while(q.length<6&&c.sword+c.archer+c.knight>0)for(const k of["sword","archer","knight"])if(c[k]>0&&q.length<6){c[k]--;q.push(k)}
 return q.map((k,i)=>[k,OFF[i]]).sort((a,b)=>a[1][1]-b[1][1]).map(([k,o])=>sdraw(SOL[k],cx+o[0],cy+o[1])).join("")}
const HO=[[-36,26],[36,26],[-62,12],[62,12]];
function heroSVG(cx,cy){return S.heroes.map((id,i)=>sdraw(HIMG[id],cx+HO[i%4][0],cy+HO[i%4][1])).join("")}
const ART_H={house:36,hall:84,farm:8,lumber:40,quarry:20,barracks:44,tower:68,wall:16};
function lvl(){const xp=S.g.reduce((a,x)=>a+(x&&x.t!=="hall"?x.lv*10:0),0)+S.wins*25+S.done.length*60;return[1+Math.floor(xp/100),xp%100]}
function cube(cx,cy,a,h,L,Rr,T){const t=cy-h;return`<polygon points="${cx-a},${t} ${cx},${t+a/2} ${cx},${cy+a/2} ${cx-a},${cy}" fill="${L}"/><polygon points="${cx},${t+a/2} ${cx+a},${t} ${cx+a},${cy} ${cx},${cy+a/2}" fill="${Rr}"/><polygon points="${cx},${t-a/2} ${cx+a},${t} ${cx},${t+a/2} ${cx-a},${t}" fill="${T}"/>`}
function roof(cx,cy,a,h,ph,L,Rr){const t=cy-h;return`<polygon points="${cx-a},${t} ${cx},${t+a/2} ${cx},${t-ph}" fill="${L}"/><polygon points="${cx},${t+a/2} ${cx+a},${t} ${cx},${t-ph}" fill="${Rr}"/>`}
function tree(x,y){return`<rect x="${x-1.5}" y="${y-4}" width="3" height="6" fill="#6b4a2a"/><polygon points="${x-9},${y-3} ${x},${y-22} ${x+9},${y-3}" fill="#2f7a3a"/><polygon points="${x-7},${y-12} ${x},${y-30} ${x+7},${y-12}" fill="#3a8c45"/>`}
function dragonArt(x,y){return`<polygon points="${x-14},${y+30} ${x-8},${y} ${x+8},${y} ${x+16},${y+30}" fill="#6b3f26"/><polygon points="${x-8},${y-8} ${x-28},${y-24} ${x-14},${y+2}" fill="#b8301f"/><polygon points="${x+8},${y-8} ${x+28},${y-24} ${x+14},${y+2}" fill="#b8301f"/><ellipse cx="${x}" cy="${y-4}" rx="9" ry="11" fill="#e0503a"/><circle cx="${x}" cy="${y-16}" r="6" fill="#e0503a"/><circle cx="${x-2.5}" cy="${y-17}" r="1.3" fill="#fff"/><circle cx="${x+2.5}" cy="${y-17}" r="1.3" fill="#fff"/><text x="${x}" y="${y+44}" text-anchor="middle" font-size="10" fill="var(--ink)">Cinder</text>`}
function art(x,cx,cy){const sp=spr(x);if(sp&&x.t!=="farm")return img(sp,cx,cy);switch(x.t){
 case"house":return cube(cx,cy,22,16,"#e6d6ae","#c9b88c","#e6d6ae")+roof(cx,cy,25,16,20,"#9a5430","#7a3f22");
 case"hall":return cube(cx,cy,30,28,"#a8613a","#84492a","#a8613a")+roof(cx,cy,34,28,30,"#2f5a3a","#234730")+`<line x1="${cx}" y1="${cy-80}" x2="${cx}" y2="${cy-58}" stroke="#4a3320" stroke-width="2"/><polygon points="${cx},${cy-80} ${cx+14},${cy-75} ${cx},${cy-70}" fill="#d9402c"/><ellipse cx="${cx+22}" cy="${cy+12}" rx="9" ry="4.5" fill="#6fb6d8"/>`;
 case"farm":{let s=`<polygon points="${cx},${cy-14} ${cx+28},${cy} ${cx},${cy+14} ${cx-28},${cy}" fill="#b98a3e"/>`;for(let t=.15;t<.9;t+=.14)s+=`<line x1="${cx-28+28*t}" y1="${cy-14*t}" x2="${cx+28*t}" y2="${cy+14-14*t}" stroke="#7a5a22" stroke-width="1.5"/>`;return s+`<circle cx="${cx-6}" cy="${cy-3}" r="3.2" fill="#f0a24a"/><circle cx="${cx+9}" cy="${cy+3}" r="3.2" fill="#f0a24a"/>`+(sp?img(sp,cx+12,cy-2):"")}
 case"lumber":return tree(cx-9,cy-2)+tree(cx+10,cy+4)+`<rect x="${cx-4}" y="${cy+6}" width="14" height="5" rx="2" fill="#9a6a3a"/>`;
 case"quarry":return`<polygon points="${cx-16},${cy+4} ${cx-6},${cy-14} ${cx+4},${cy-4} ${cx+2},${cy+8}" fill="#9aa4aa"/><polygon points="${cx+2},${cy+8} ${cx+4},${cy-4} ${cx+16},${cy-8} ${cx+20},${cy+6}" fill="#7d878d"/>`;
 case"barracks":{let s=cube(cx,cy,26,16,"#c55a48","#9e4333","#d46c58")+roof(cx,cy,29,16,12,"#6b6f73","#55595c")+`<line x1="${cx}" y1="${cy-44}" x2="${cx}" y2="${cy-28}" stroke="#4a3320" stroke-width="2"/><polygon points="${cx},${cy-44} ${cx+12},${cy-40} ${cx},${cy-36}" fill="#d9402c"/>`;for(let k=0;k<Math.min(tCount(),6);k++)s+=`<circle cx="${cx-15+k*6}" cy="${cy+15}" r="2.6" fill="#fff" stroke="#9e4333"/>`;return s}
 case"tower":return cube(cx,cy,11,46,"#b9bfc3","#9aa0a4","#b9bfc3")+roof(cx,cy,14,46,16,"#9a5430","#7a3f22");
 case"wall":return cube(cx,cy,28,8,"#a9aeb2","#8b9094","#c0c5c8")}return""}
function tileSVG(x,i,cx,cy){
 const sl=sel===i,ev=(i%10+Math.floor(i/10))%2;
 let s=`<g data-a="tile" data-v="${i}" role="button" aria-label="${x?BT[x.t].n:"Empty plot"}" style="cursor:pointer"><polygon points="${cx},${cy-16} ${cx+32},${cy} ${cx},${cy+16} ${cx-32},${cy}" fill="${["#668a45","#71964b","#698e46","#75974c"][(i*13+Math.floor(i/10))%4]}" stroke="${sl||(mv>=0&&!x)?"var(--gold)":"#0001"}" stroke-width="${sl?3:(mv>=0&&!x?2:1)}"/>`;
 if(x){s+=`<ellipse cx="${cx}" cy="${cy+8}" rx="25" ry="9" fill="#152519" opacity=".32" pointer-events="none"/><g opacity="${(x.b||mv===i)?.45:1}">${art(x,cx,cy)}</g>`;const sp0=spr(x),top=sp0?cy+17-sp0.h-6:cy-ART_H[x.t]-8;
  if(x.b)s+=`<rect x="${cx-16}" y="${top}" width="32" height="5" rx="2" fill="#0008"/><rect x="${cx-16}" y="${top}" width="${32*(1-x.b/x.bt)}" height="5" rx="2" fill="#8fc16a"/>`;
  else{const st=Math.floor(x.s||0);if(st>=5)s+=`<circle cx="${cx}" cy="${top}" r="10" fill="#e8b94a" stroke="#2b2008"/><text x="${cx}" y="${top+4}" text-anchor="middle" font-size="11" font-weight="700" fill="#2b2008">${st}</text>`}
  if(x.lv>1)s+=`<circle cx="${cx-24}" cy="${cy+4}" r="8" fill="#000a"/><text x="${cx-24}" y="${cy+8}" text-anchor="middle" font-size="10" fill="#fff">${x.lv}</text>`}
 return s+"</g>"}
let camera={z:1,x:288,y:166};
function iso(){
 let s=`<svg viewBox="${camera.x-288/camera.z} ${camera.y-166/camera.z} ${576/camera.z} ${332/camera.z}" role="img" aria-label="Your village" style="width:100%;height:auto;display:block"><defs><radialGradient id="land"><stop stop-color="#72974d"/><stop offset="1" stop-color="#304c30"/></radialGradient><pattern id="grass" width="19" height="17" patternUnits="userSpaceOnUse"><path d="M3 8l2 -4 1 4m9 6l1 -3 2 3" stroke="#d0db82" stroke-opacity=".19" fill="none"/></pattern></defs><rect width="576" height="332" fill="url(#land)"/><rect width="576" height="332" fill="url(#grass)"/>`;
 [[26,50],[40,300],[548,60],[540,300],[300,326],[18,170],[560,180],[65,65],[90,38],[130,25],[485,35],[520,85],[50,265],[100,295],[470,300],[510,268],[550,245]].forEach(([x,y])=>s+=tree(x,y));
 for(let i=0;i<55;i++){let x=(i*97+13)%576,y=(i*53+7)%332; if(Math.abs(x-288)/285+Math.abs(y-165)/145>1.05)s+=`<ellipse cx="${x}" cy="${y}" rx="4" ry="2" fill="${i%3?'#456b36':'#8d9480'}"/><circle cx="${x+2}" cy="${y-2}" r="1" fill="#c5c18a"/>`;}
 if(S.dragon)s+=dragonArt(70,110);
 const key=i=>i%10+Math.floor(i/10);
 S.g.map((x,i)=>i).sort((a,b)=>key(a)-key(b)).forEach(i=>{const c=i%10,r=Math.floor(i/10);s+=tileSVG(S.g[i],i,(c-r)*32+256,(c+r)*16+52)});
 s+=`<g pointer-events="none">`;S.g.forEach((x,i)=>{if(x&&!x.b&&!S.quest&&!S.battle){const c=i%10,r=Math.floor(i/10),cx=(c-r)*32+256,cy=(c+r)*16+52;if(x.t==="barracks")s+=squad(cx,cy);if(x.t==="hall")s+=heroSVG(cx,cy)}});
 if(S.battle){s+=battleArt()}else if(!S.protection){const pr=Math.min(1,Math.max(0,1-S.raidIn/100)),O=[[0,0],[-28,-12],[-52,6],[-78,-4]];enemyGroup(S.wave+1).slice(0,4).map((m,j)=>[m,O[j]]).sort((a,b)=>a[1][1]-b[1][1]).forEach(([m,o])=>{s+=`<g class="monster-bob">${sdraw(m,40+190*pr+o[0],62+95*pr+o[1])}</g>`})}
 return s+"</g></svg>"}
function save(){try{S.ts=Date.now();localStorage.setItem("emberhold2",JSON.stringify(S))}catch(e){}}
function load(){try{const j=localStorage.getItem("emberhold2");if(!j)return;const old=JSON.parse(j);S=Object.assign(fresh(),old);if(old.protection===undefined)S.protection=0;const away=Math.min(7200,Math.floor((Date.now()-(S.ts||Date.now()))/1000));if(away>30){const ef=effv();S.g.forEach(x=>{if(!x)return;if(x.b>0){x.b-=away;if(x.b<=0)fin(x)}const d=BT[x.t];if(d.p&&!x.b)x.s=Math.min(CAP,(x.s||0)+d.r*(1+.4*(x.lv-1))*(d.w?ef:1)*away*.5)});S.raidIn=Math.max(S.raidIn,30);log(`Welcome back! After ${Math.floor(away/60)} min away, your buildings kept working at half pace.`,"win")}}catch(e){}}
load();draw();setInterval(tick,1000);

function updateCamera(){const v=$("grid").querySelector("svg");if(v)v.setAttribute("viewBox",`${camera.x-288/camera.z} ${camera.y-166/camera.z} ${576/camera.z} ${332/camera.z}`);$("zoomRead").textContent=Math.round(camera.z*100)+"%";}
function clampCamera(){camera.x=Math.max(288/camera.z,Math.min(576-288/camera.z,camera.x));camera.y=Math.max(166/camera.z,Math.min(332-166/camera.z,camera.y));}
function zoomBy(n){camera.z=Math.max(1,Math.min(2.5,camera.z+n));clampCamera();updateCamera();}
$("zoomIn").onclick=()=>zoomBy(.25);$("zoomOut").onclick=()=>zoomBy(-.25);$("zoomReset").onclick=()=>{camera={z:1,x:288,y:166};updateCamera()};
let pan=null,panMode=false;const mapEl=$("grid");$("panToggle").onclick=()=>{panMode=!panMode;$("panToggle").setAttribute("aria-pressed",String(panMode));mapEl.classList.toggle("pan-mode",panMode)};
mapEl.addEventListener("pointerdown",e=>{if(!panMode&&e.button!==1&&!e.shiftKey)return;e.preventDefault();e.stopPropagation();pan={id:e.pointerId,x:e.clientX,y:e.clientY};mapEl.setPointerCapture(e.pointerId);},true);
mapEl.addEventListener("pointermove",e=>{if(!pan||pan.id!==e.pointerId)return;const r=mapEl.getBoundingClientRect();camera.x-=(e.clientX-pan.x)*576/camera.z/r.width;camera.y-=(e.clientY-pan.y)*332/camera.z/r.height;pan.x=e.clientX;pan.y=e.clientY;clampCamera();updateCamera()});
for(const k of ["pointerup","pointercancel","lostpointercapture"])mapEl.addEventListener(k,()=>{pan=null});

function battleStep(){const b=S.battle;b.round++;const a=Math.max(1,b.p)*10,e=b.q*10;const n=6;const frac=Math.min(1,b.round/n);const old=b.hp,oe=b.ehp;b.hp=Math.max(0,Math.round(a*(1-frac*(b.win?.55:1))));b.ehp=Math.max(0,Math.round(e*(1-frac*(b.win?1:Math.min(.8,b.p/b.q)))));b.hit=old-b.hp;b.ehit=oe-b.ehp;if(b.round>=n)resolveRaid();}
function battleHUD(){const b=S.battle;return `<b>⚔ Wave ${S.wave+1} · Auto battle</b><div class="combat-hud"><div>Kingdom HP ${b.hp}<div class="bar"><i style="background:#76b86a;width:${100*b.hp/(Math.max(1,b.p)*10)}%"></i></div></div><div>Horde HP ${b.ehp}<div class="bar"><i style="width:${100*b.ehp/(b.q*10)}%"></i></div></div></div>`;}
function battleArt(){const b=S.battle;let s='', units=[];for(const k of Object.keys(TROOPS))for(let i=0;i<Math.min(3,b.units[k]);i++)units.push(SOL[k]);for(const id of b.heroes)units.push(HIMG[id]);const pr=Math.min(1,b.round/2);const ax=390-95*pr,ex=90+115*pr;const hp=(x,y,v,c)=>`<rect x="${x-15}" y="${y-4}" width="30" height="4" fill="#171714"/><rect x="${x-15}" y="${y-4}" width="${30*v}" height="4" fill="${c}"/>`;units.slice(0,8).forEach((u,i)=>{let x=ax+(i%3)*22,y=190+Math.floor(i/3)*22;s+=`<g class="fighter ally">${sdraw(u,x,y)}${hp(x,y-u.h-4,b.hp/(Math.max(1,b.p)*10),'#79c76d')}</g>`});enemyGroup(S.wave+1).forEach((u,i)=>{let x=ex-(i%3)*24,y=185+Math.floor(i/3)*26;s+=`<g class="fighter enemy">${sdraw(u,x,y)}${hp(x,y-u.h-4,b.ehp/(b.q*10),'#e86552')}</g>`});if(b.round){s+=`<text class="damage" x="${ax}" y="135" fill="#ffb5a0">-${b.hit}</text><text class="damage" x="${ex}" y="135" fill="#ffe19a">-${b.ehit}</text>`;}return s;}
function showResult(){const d=$("battleResult");if(!d||!S.last)return;$("battleTitle").textContent=S.last.win?"Victory!":"Defeat";$("battleTitle").style.color=S.last.win?"#a7d78b":"#ff987f";$("battleText").innerHTML=S.last.t;d.hidden=false;}
$("battleClose").onclick=()=>{$("battleResult").hidden=true};
